#!/usr/bin/env python3
# -*- coding: utf-8 -*-
#
# Prepare GitTaskBench repositories in the current workspace.
# Uses meta.json (generated by adapter_gittaskbench.py).

from __future__ import annotations

import json
import shutil
from pathlib import Path


def _copy_tree(src: Path, dst: Path) -> None:
    if dst.exists():
        shutil.rmtree(dst, ignore_errors=True)
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copytree(src, dst, symlinks=True)


def main() -> int:
    root = Path(__file__).resolve().parent
    meta_path = root / "meta.json"
    if not meta_path.exists():
        print("meta.json missing")
        return 2
    meta = json.loads(meta_path.read_text(encoding="utf-8"))
    repos = meta.get("repos") if isinstance(meta.get("repos"), list) else []
    if not repos:
        print("no repos to prepare")
        return 0
    for r in repos:
        src = Path(str(r.get("src_path") or "")).expanduser().resolve()
        dst = root / str(r.get("dst_path") or "")
        if not src.exists():
            print(f"repo src missing: {src}")
            return 2
        _copy_tree(src, dst)
    print("repos prepared")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
